export const toneSections = [
  { title: L("Partir d’un contrat", "Start with a contract"), text: L("Un client veut récupérer une technologie, protéger une personne, escorter une livraison ou entrer quelque part sans y être invité. Donnez à la crew un objectif compréhensible, une rémunération et des moyens de préparer son intervention au Hub. Le trajet à travers Paradise peut ensuite révéler un intérêt caché, une communauté inattendue ou un adversaire bien plus équipé qu’annoncé. Une affaire de quartier peut rester modeste ; une opération corporate peut devenir spectaculaire. L’ampleur du contrat ne mesure pas à elle seule ce que les personnages ont à y gagner ou à y perdre.", "A client wants to recover technology, protect someone, escort a delivery or enter somewhere uninvited. Give the crew a clear objective, payment and ways to prepare at the Hub. The journey through Paradise can then reveal a hidden interest, an unexpected community or an opponent much better equipped than advertised. A neighborhood job can stay modest; a corporate operation can become spectacular. A contract’s scale alone does not measure what the characters stand to gain or lose.") },
  { title: L('Donner une raison à chaque camp', 'Give every side a reason'), text: L('Les personnes rencontrées ont souvent une bonne raison de vouloir conserver une partie de la situation. Un technicien tient à son atelier, un patient au traitement qui l’aide, un délégué à l’accord qui fait vivre ses collègues. Faites apparaître ce qu’ils craignent de perdre autant que ce qu’ils réclament. Comprendre ces intérêts ne les rend pas tous acceptables ; cela permet aux joueurs de choisir à qui faire confiance et quel prix ils refusent de payer.', 'People often have good reasons to preserve part of a situation. A technician cares about a workshop, a patient about useful treatment, a delegate about an agreement supporting colleagues. Show what they fear losing as well as what they demand. Understanding those interests does not make them all acceptable; it lets players choose whom to trust and which price they refuse to pay.') },
  { title: L("Faire exister le progrès", "Make progress tangible"), text: L("Les technologies de Paradise accomplissent réellement des merveilles. Montrez ce qu’un implant, un robot ou une résurrection permet de faire, puis les choix que son accès ouvre aux personnages. La boucle du Hub lie contrats, chroma, équipement et nouvelles ambitions : le retour au marché peut compter autant que le départ. Les limites matérielles, les clauses et les pannes deviennent intéressantes lorsqu’elles pèsent sur une situation précise ; elles ne doivent pas transformer chaque usage en échec ni ajouter des pénalités absentes des règles.", "Paradise’s technologies genuinely perform wonders. Show what an implant, robot or resurrection enables, then the choices that access opens for characters. The Hub’s cycle connects contracts, chroma, equipment and new ambitions: returning to the market can matter as much as setting out. Physical limits, contract terms and breakdowns become interesting when they affect a particular situation; they should not turn every use into failure or add penalties absent from the rules.") },
  { title: L('Laisser de la place aux attaches', 'Leave room for attachments'), text: L('Laissez revenir les repas, les plaisanteries et les rendez-vous qui ne demandent rien d’autre que d’être là. Un café partagé ou un match commenté donne une existence aux habitants au-delà des contrats qu’ils proposent. Ces moments peuvent rester heureux, maladroits ou simplement ordinaires. Lorsque les personnages choisissent ensuite de défendre une personne ou un lieu, ils savent ce qu’ils espèrent retrouver une fois l’affaire terminée.', 'Let meals, jokes and gatherings recur without asking anything beyond being there. Shared coffee or a discussion of a match gives residents lives beyond the contracts they offer. These moments can remain happy, awkward or simply ordinary. When characters later choose to defend a person or place, they know what they hope to return to once the affair is over.') },
];

// Rich paragraphs keep emphasis and translate each rendered text segment.
const R = (fr, en) => {
  const source = fr.split(/\*\*(.*?)\*\*/g);
  const target = en.split(/\*\*(.*?)\*\*/g);
  if (source.length !== target.length) throw new Error('Mismatched bilingual emphasis');
  source.forEach((text, i) => { if (text.trim()) L(text, target[i]); });
  return fr;
};

